// Safe lookup: .item can be undefined when the AI Agent errors (pairing is lost).
function nodeJson(name) {
  try {
    const it = $(name).item;
    if (it?.json) return it.json;
  } catch (e) {}
  try { return $(name).first()?.json ?? {}; } catch (e) { return {}; }
}

const prepared = nodeJson('Prepare WhatsApp message');
const trigger = nodeJson('WhatsApp Trigger');
const input = $input.item.json;

function parseValue(value) {
  if (typeof value !== 'string') return value;
  const cleaned = value.trim()
    .replace(/^\x60\x60\x60(?:json)?\s*/i, '')
    .replace(/\s*\x60\x60\x60$/, '');
  return JSON.parse(cleaned);
}

let response;
let parseError = '';

try {
  response = parseValue(input.output ?? input);

  // Remove any extra "output" wrappers.
  for (let i = 0; i < 3; i++) {
    if (response && typeof response === 'object' &&
        !('reply' in response) && 'output' in response) {
      response = parseValue(response.output);
    } else {
      break;
    }
  }

  if (!response || typeof response.reply !== 'string' ||
      !Object.prototype.hasOwnProperty.call(response, 'order')) {
    throw new Error('Invalid AI response structure');
  }
} catch (error) {
  parseError = input.error
    ? 'AI Agent error: ' + (input.error.message ?? JSON.stringify(input.error))
    : error.message;
  return {
    json: {
      reply: "We're checking your request. Our team will update you shortly.",
      orderReady: false,
      teamMessage: "",
      parseError
    }
  };
}

// Get the original WhatsApp message.
const originalMessage =
  trigger.messages?.[0] ??
  trigger.entry?.[0]?.changes?.[0]?.value?.messages?.[0] ??
  trigger.message ??
  null;

// WhatsApp number must come from webhook, not AI.
const whatsapp = String(
  originalMessage?.from ??
  prepared.whatsapp ??
  prepared.from ??
  trigger.contacts?.[0]?.wa_id ??
  ''
).trim();

// Original current or previously saved location.
const currentLocation =
  originalMessage?.type === 'location'
    ? originalMessage.location
    : null;

const savedLocation =
  prepared.savedLocationPayload ??
  prepared.locationPayload ??
  null;

function isValidLocation(loc) {
  return loc && typeof loc === 'object' &&
    Number.isFinite(Number(loc.latitude)) &&
    Number.isFinite(Number(loc.longitude)) &&
    loc.latitude !== '' && loc.longitude !== '';
}

const location =
  isValidLocation(currentLocation) ? currentLocation :
  isValidLocation(savedLocation) ? savedLocation :
  null;

const order = response.order;

const required = [
  'battery', 'price', 'car', 'name', 'contact'
];

const validOrder = Boolean(
  order &&
  typeof order === 'object' &&
  required.every(key =>
    typeof order[key] === 'string' &&
    order[key].trim() !== ''
  )
);

const alreadySubmitted = prepared.orderSubmitted === true;

const orderReady = Boolean(
  validOrder &&
  whatsapp &&
  location &&
  !alreadySubmitted
);

const teamMessage = orderReady
  ? [
      'NEW BATTERY ORDER',
      'Customer: ' + order.name,
      'WhatsApp: ' + whatsapp,
      'Local Contact: ' + order.contact,
      'Car: ' + order.car,
      'Battery: ' + order.battery,
      'Price: ' + order.price,
      'Location: Customer location pin follows 📍'
    ].join('\n')
  : '';

return {
  json: {
    reply: response.reply,
    orderReady,
    teamMessage,
    whatsapp,
    order: validOrder ? order : null,
    locationPayload: location,
    parseError
  }
};

const results = [];
for (const [index, item] of $input.all().entries()) {
  const message = item.json.messages?.[0];
  if (!message?.from) continue;
  let chatInput;
  let locationPin;
  let hasImage = false;
  let imageId = '';
  let caption = '';
  if (message.type === 'text') {
    chatInput = message.text?.body?.trim();
  } else if (message.type === 'location') {
    const lat = Number(message.location?.latitude);
    const lng = Number(message.location?.longitude);
    if (!Number.isFinite(lat) || !Number.isFinite(lng) || Math.abs(lat) > 90 || Math.abs(lng) > 180) continue;
    locationPin = { latitude: lat, longitude: lng, name: message.location?.name || '', address: message.location?.address || '' };
    chatInput = '[Customer shared a WhatsApp delivery location pin. No coordinates are shown to you. Complete the order only if the selected battery, car, name and contact number are already known.]';
  } else if (message.type === 'image' && message.image?.id) {
    hasImage = true;
    imageId = message.image.id;
    caption = message.image.caption?.trim() || '';
    chatInput = '[Customer sent a battery photo]' + (caption ? ' Caption: ' + caption : '');
  } else {
    continue;
  }
  if (!chatInput) continue;
  const phoneId = item.json.metadata?.phone_number_id || 'YOUR_WHATSAPP_PHONE_NUMBER_ID';
  results.push({
    json: {
      ...item.json,
      chatInput,
      locationPin,
      hasImage,
      imageId,
      caption,
      sender: message.from,
      sessionId: 'whatsapp:' + phoneId + ':' + message.from
    },
    pairedItem: { item: index }
  });
}
return results;

