const prepared = $('Prepare WhatsApp message').item.json;
const raw = $input.item.json.output;

let analysis = null;
try {
  analysis = typeof raw === 'string'
    ? JSON.parse(raw.trim().replace(/^\x60\x60\x60(?:json)?\s*/i, '').replace(/\s*\x60\x60\x60$/, ''))
    : (raw && typeof raw === 'object' ? raw : null);
} catch (e) {
  analysis = null;
}

if (!analysis) {
  analysis = { is_battery: false, readable: false, notes: 'Photo could not be downloaded or analysed.' };
}

const chatInput = [
  '[BATTERY PHOTO ANALYSIS — produced by the Battery Vision Agent from the customer photo]',
  JSON.stringify(analysis),
  'Customer caption: ' + (prepared.caption || 'none')
].join('\n');

return { json: { ...prepared, chatInput, photoAnalysis: analysis } };
